(()=>{const video=document.querySelector('#studio-walkthrough');if(!video)return;video.muted=true;video.controls=false;let visible=false;const update=()=>{if(visible&&!document.hidden)video.play().catch(()=>{});else video.pause()};new IntersectionObserver(([e])=>{visible=e.isIntersecting;update()},{threshold:.1}).observe(video);document.addEventListener('visibilitychange',update);addEventListener('pagehide',()=>video.pause())})();